 "content": "def transform(grid):
    """Between consecutive occurrences of the same non-background color in a
    row or column, color intervening background cells 2."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Complete horizontal gaps, independently for each foreground color.
    for r in range(h):
        for color in set(grid[r]) - {bg}:
            positions = [c for c, value in enumerate(grid[r]) if value == color]
            for left, right in zip(positions, positions[1:]):
                for c in range(left + 1, right):
                    if grid[r][c] == bg:
                        out[r][c] = 2

    # Complete vertical gaps, independently for each foreground color.
    for c in range(w):
        colors = {grid[r][c] for r in range(h)} - {bg}
        for color in colors:
            positions = [r for r in range(h) if grid[r][c] == color]
            for top, bottom in zip(positions, positions[1:]):
                for r in range(top + 1, bottom):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out

if __name__ == '__main__':
