 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts)
    c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]
    for r in (r0, r1):
        marks = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                out[r][c] = 2
    for c in (c0, c1):
        marks = [r for r in range(r0, r1 + 1) if grid[r][c] != bg]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
